CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(120) NOT NULL UNIQUE, sku VARCHAR(80) NULL UNIQUE, short_description TEXT NULL, source_images TEXT NULL, name VARCHAR(140) NOT NULL, category VARCHAR(100) NOT NULL DEFAULT '', description TEXT NOT NULL, price INT UNSIGNED NOT NULL, image VARCHAR(255) NOT NULL, back_image VARCHAR(255) NULL, active TINYINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS variants (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, size VARCHAR(10) NOT NULL, stock INT UNSIGNED NULL, UNIQUE KEY product_size(product_id,size), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(80) PRIMARY KEY, value TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(32) NOT NULL UNIQUE, access_token CHAR(64) NOT NULL UNIQUE, checkout_key CHAR(64) NOT NULL UNIQUE, customer_name VARCHAR(120) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(190) NOT NULL DEFAULT '', address TEXT NOT NULL, area VARCHAR(30) NOT NULL, notes TEXT NOT NULL, subtotal INT UNSIGNED NOT NULL, delivery_fee INT UNSIGNED NULL, total INT UNSIGNED NULL, payment_method VARCHAR(30) NOT NULL DEFAULT 'cod', payment_status VARCHAR(30) NOT NULL DEFAULT 'unpaid', status VARCHAR(30) NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, product_name VARCHAR(140) NOT NULL, size VARCHAR(10) NOT NULL, unit_price INT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, stock_reserved TINYINT NOT NULL DEFAULT 0, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (ip_hash CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, last_attempt DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
